VALUES ('neial-013', 'NEIAL-013', 'NotEverythingIsALanguage', 'Observation', 'FuzzyBoundary', 'Fuzzy case: Running Calculator App often contains embedded languages (code, UI grammars), but as an executing/interactive process it behaves like a dynamic system rather than a static serialized language artifact.', 'Borderline(Running Calculator App): may contain ∃y Language(y) but ¬Language(Running Calculator App) under static-serialization criteria', 'Running Calculator App', 'running-calculator-app', 'HasSyntax=False; RequiresParsing=True; HasLinearDecodingPressure=False; IsOngologyDescriptor=False; CanBeHeld=False; HasIdentity=True; DistanceFromConcept=1; Category=Running Software', 'This is where traditional semiotics'' ''anything is a sign'' doesn’t neatly distinguish: (1) language-as-system vs (2) meaning-making interactive processes.') ON CONFLICT (is_everything_a_language_id) DO UPDATE SET name = EXCLUDED.name, argument_name = EXCLUDED.argument_name, argument_category = EXCLUDED.argument_category, step_type = EXCLUDED.step_type, statement = EXCLUDED.statement, formalization = EXCLUDED.formalization, related_candidate_name = EXCLUDED.related_candidate_name, related_candidate_id = EXCLUDED.related_candidate_id, evidence_from_rulebook = EXCLUDED.evidence_from_rulebook, notes = EXCLUDED.notes;

