VALUES ('neial-014', 'NEIAL-014', 'NotEverythingIsALanguage', 'Observation', 'FuzzyBoundary', 'Fuzzy case: A Game of Fortnite often contains embedded languages (code, UI grammars), but as an executing/interactive process it behaves like a dynamic system rather than a static serialized language artifact.', 'Borderline(A Game of Fortnite): may contain ∃y Language(y) but ¬Language(A Game of Fortnite) under static-serialization criteria', 'A Game of Fortnite', 'a-game-of-fortnite', 'HasSyntax=False; RequiresParsing=True; HasLinearDecodingPressure=False; IsOngologyDescriptor=False; CanBeHeld=False; HasIdentity=True; DistanceFromConcept=1; Category=Running Software', 'This is where traditional semiotics'' ''anything is a sign'' doesn’t neatly distinguish: (1) language-as-system vs (2) meaning-making interactive processes.') ON CONFLICT (is_everything_a_language_id) DO UPDATE SET name = EXCLUDED.name, argument_name = EXCLUDED.argument_name, argument_category = EXCLUDED.argument_category, step_type = EXCLUDED.step_type, statement = EXCLUDED.statement, formalization = EXCLUDED.formalization, related_candidate_name = EXCLUDED.related_candidate_name, related_candidate_id = EXCLUDED.related_candidate_id, evidence_from_rulebook = EXCLUDED.evidence_from_rulebook, notes = EXCLUDED.notes;

INSERT INTO is_everything_a_language (is_everything_a_language_id, name, argument_name, argument_category, step_type, statement, formalization, related_candidate_name, related_candidate_id, evidence_from_rulebook, notes)
VALUES ('neial-015', 'NEIAL-015', 'NotEverythingIsALanguage', 'Definition', 'Refinement', 'Refinement: distinguish LanguageSystem (syntax/parsing/serialization descriptor) from SemioticProcess (interactive/dynamic meaning production) and from SignVehicle (object/phenomenon used as a sign).', 'Kinds: LanguageSystem(x) | SemioticProcess(x) | SignVehicle(x)', '', '', '', 'This gives you a place to put running apps and games without forcing ''language'' to swallow everything.') ON CONFLICT (is_everything_a_language_id) DO UPDATE SET name = EXCLUDED.name, argument_name = EXCLUDED.argument_name, argument_category = EXCLUDED.argument_category, step_type = EXCLUDED.step_type, statement = EXCLUDED.statement, formalization = EXCLUDED.formalization, related_candidate_name = EXCLUDED.related_candidate_name, related_candidate_id = EXCLUDED.related_candidate_id, evidence_from_rulebook = EXCLUDED.evidence_from_rulebook, notes = EXCLUDED.notes;

INSERT INTO is_everything_a_language (is_everything_a_language_id, name, argument_name, argument_category, step_type, statement, formalization, related_candidate_name, related_candidate_id, evidence_from_rulebook, notes)
VALUES ('neial-016', 'NEIAL-016', 'NotEverythingIsALanguage', 'Conclusion', 'Conclusion', 'Given a formalizable definition of language, not everything is a language; some things are better treated as sign vehicles or semiotic processes, with running applications as a key fuzzy region that benefits from explicit modeling.', 'Formalizable(Language) ∧ ∃x ¬Language(x) ⇒ ¬(EverythingIsALanguage)', '', '', '', 'This is the repo''s thesis in one line.') ON CONFLICT (is_everything_a_language_id) DO UPDATE SET name = EXCLUDED.name, argument_name = EXCLUDED.argument_name, argument_category = EXCLUDED.argument_category, step_type = EXCLUDED.step_type, statement = EXCLUDED.statement, formalization = EXCLUDED.formalization, related_candidate_name = EXCLUDED.related_candidate_name, related_candidate_id = EXCLUDED.related_candidate_id, evidence_from_rulebook = EXCLUDED.evidence_from_rulebook, notes = EXCLUDED.notes;

