VALUES ('specialization', 'Specialization', 6, 'The signal exists in order to communicate, rather than being a side effect of some other behaviour.', TRUE, 'Hockett, C. F. (1960). The Origin of Speech. Scientific American 203(3), 88-96. Features 14-16 were added in Hockett & Altmann (1968).') ON CONFLICT (hockett_feature_id) DO UPDATE SET name = EXCLUDED.name, feature_number = EXCLUDED.feature_number, definition = EXCLUDED.definition, is_original_thirteen = EXCLUDED.is_original_thirteen, source = EXCLUDED.source;

INSERT INTO hockett_features (hockett_feature_id, name, feature_number, definition, is_original_thirteen, source)
VALUES ('semanticity', 'Semanticity', 7, 'Signals carry fixed associations to things and situations in the world.', TRUE, 'Hockett, C. F. (1960). The Origin of Speech. Scientific American 203(3), 88-96. Features 14-16 were added in Hockett & Altmann (1968).') ON CONFLICT (hockett_feature_id) DO UPDATE SET name = EXCLUDED.name, feature_number = EXCLUDED.feature_number, definition = EXCLUDED.definition, is_original_thirteen = EXCLUDED.is_original_thirteen, source = EXCLUDED.source;

INSERT INTO hockett_features (hockett_feature_id, name, feature_number, definition, is_original_thirteen, source)
VALUES ('arbitrariness', 'Arbitrariness', 8, 'The tie between a signal and its meaning is conventional rather than a resemblance.', TRUE, 'Hockett, C. F. (1960). The Origin of Speech. Scientific American 203(3), 88-96. Features 14-16 were added in Hockett & Altmann (1968).') ON CONFLICT (hockett_feature_id) DO UPDATE SET name = EXCLUDED.name, feature_number = EXCLUDED.feature_number, definition = EXCLUDED.definition, is_original_thirteen = EXCLUDED.is_original_thirteen, source = EXCLUDED.source;

INSERT INTO hockett_features (hockett_feature_id, name, feature_number, definition, is_original_thirteen, source)
VALUES ('discreteness', 'Discreteness', 9, 'The signal is built from a repertoire of distinct units, so a small deviation either switches units outright or is heard as a noisy version of the same one.', TRUE, 'Hockett, C. F. (1960). The Origin of Speech. Scientific American 203(3), 88-96. Features 14-16 were added in Hockett & Altmann (1968).') ON CONFLICT (hockett_feature_id) DO UPDATE SET name = EXCLUDED.name, feature_number = EXCLUDED.feature_number, definition = EXCLUDED.definition, is_original_thirteen = EXCLUDED.is_original_thirteen, source = EXCLUDED.source;

INSERT INTO hockett_features (hockett_feature_id, name, feature_number, definition, is_original_thirteen, source)
VALUES ('displacement', 'Displacement', 10, 'Messages can be about things remote in time or space.', TRUE, 'Hockett, C. F. (1960). The Origin of Speech. Scientific American 203(3), 88-96. Features 14-16 were added in Hockett & Altmann (1968).') ON CONFLICT (hockett_feature_id) DO UPDATE SET name = EXCLUDED.name, feature_number = EXCLUDED.feature_number, definition = EXCLUDED.definition, is_original_thirteen = EXCLUDED.is_original_thirteen, source = EXCLUDED.source;

INSERT INTO hockett_features (hockett_feature_id, name, feature_number, definition, is_original_thirteen, source)
VALUES ('productivity', 'Productivity', 11, 'Messages never sent before can be produced and understood.', TRUE, 'Hockett, C. F. (1960). The Origin of Speech. Scientific American 203(3), 88-96. Features 14-16 were added in Hockett & Altmann (1968).') ON CONFLICT (hockett_feature_id) DO UPDATE SET name = EXCLUDED.name, feature_number = EXCLUDED.feature_number, definition = EXCLUDED.definition, is_original_thirteen = EXCLUDED.is_original_thirteen, source = EXCLUDED.source;

INSERT INTO hockett_features (hockett_feature_id, name, feature_number, definition, is_original_thirteen, source)
VALUES ('traditional-transmission', 'Traditional Transmission', 12, 'The system is learned from other users rather than inherited genetically.', TRUE, 'Hockett, C. F. (1960). The Origin of Speech. Scientific American 203(3), 88-96. Features 14-16 were added in Hockett & Altmann (1968).') ON CONFLICT (hockett_feature_id) DO UPDATE SET name = EXCLUDED.name, feature_number = EXCLUDED.feature_number, definition = EXCLUDED.definition, is_original_thirteen = EXCLUDED.is_original_thirteen, source = EXCLUDED.source;

INSERT INTO hockett_features (hockett_feature_id, name, feature_number, definition, is_original_thirteen, source)
VALUES ('duality-of-patterning', 'Duality Of Patterning', 13, 'A small stock of meaningless units combines into a large stock of meaningful ones.', TRUE, 'Hockett, C. F. (1960). The Origin of Speech. Scientific American 203(3), 88-96. Features 14-16 were added in Hockett & Altmann (1968).') ON CONFLICT (hockett_feature_id) DO UPDATE SET name = EXCLUDED.name, feature_number = EXCLUDED.feature_number, definition = EXCLUDED.definition, is_original_thirteen = EXCLUDED.is_original_thirteen, source = EXCLUDED.source;

INSERT INTO hockett_features (hockett_feature_id, name, feature_number, definition, is_original_thirteen, source)
VALUES ('prevarication', 'Prevarication', 14, 'Messages can be false, deceptive or meaningless.', FALSE, 'Hockett, C. F. (1960). The Origin of Speech. Scientific American 203(3), 88-96. Features 14-16 were added in Hockett & Altmann (1968).') ON CONFLICT (hockett_feature_id) DO UPDATE SET name = EXCLUDED.name, feature_number = EXCLUDED.feature_number, definition = EXCLUDED.definition, is_original_thirteen = EXCLUDED.is_original_thirteen, source = EXCLUDED.source;

INSERT INTO hockett_features (hockett_feature_id, name, feature_number, definition, is_original_thirteen, source)
VALUES ('reflexiveness', 'Reflexiveness', 15, 'The system can be used to communicate about itself.', FALSE, 'Hockett, C. F. (1960). The Origin of Speech. Scientific American 203(3), 88-96. Features 14-16 were added in Hockett & Altmann (1968).') ON CONFLICT (hockett_feature_id) DO UPDATE SET name = EXCLUDED.name, feature_number = EXCLUDED.feature_number, definition = EXCLUDED.definition, is_original_thirteen = EXCLUDED.is_original_thirteen, source = EXCLUDED.source;

INSERT INTO hockett_features (hockett_feature_id, name, feature_number, definition, is_original_thirteen, source)
VALUES ('learnability', 'Learnability', 16, 'A user of one such system can learn another.', FALSE, 'Hockett, C. F. (1960). The Origin of Speech. Scientific American 203(3), 88-96. Features 14-16 were added in Hockett & Altmann (1968).') ON CONFLICT (hockett_feature_id) DO UPDATE SET name = EXCLUDED.name, feature_number = EXCLUDED.feature_number, definition = EXCLUDED.definition, is_original_thirteen = EXCLUDED.is_original_thirteen, source = EXCLUDED.source;

